// Illustrator's default keyboard shortcuts, every row of Adobe's published
// table, and what each one means in PlexiiDraw.
//
// Source: Adobe, "Default keyboard shortcuts | Illustrator",
// https://helpx.adobe.com/illustrator/using/default-keyboard-shortcuts.html
// helpx answers scripted requests with 403, so the rows were read on
// 2026-10-21 from the Internet Archive's capture of that page taken
// 2026-10-15 (web.archive.org/web/20261015081538/<the URL above>). Action names
// and key texts are Adobe's, verbatim; rows the page prints twice (the paint
// rows under both "Edit shapes" and "Work with objects") appear once.
//
// Where the page's macOS cell is visibly broken the key comes from the Windows
// cell: "Toggle line composer" (cut off), "Release guides" (says Ctrl),
// "Subscript" (repeats the Windows keys), "Underline" and "Select the object
// below the current selection" (lost a character). "Show/Hide artboard rulers"
// is the one genuine platform difference: Ctrl+R on Windows, Cmd+Option+R on
// a Mac.
//
// context:
//   'global'   a chord pressed on the canvas -- these are what the keymap
//              implements or reserves; `key` is in keymap.ts form.
//   'type'     a key for editing text; it belongs to the text editor, never to
//              the canvas keymap (several reuse canvas chords, e.g. Shift+Cmd+B
//              is Bold while typing and Hide bounding box otherwise).
//   'gesture'  a modifier held during a click or drag, a key pressed mid-drag,
//              or a key inside a panel field: tool and panel behaviour, not a
//              keymap entry.
// target (global rows only):
//   'cmd:<id>'  bound to that command in KEYMAP
//   'tool:<id>' that tool's key
//   'res:<id>'  reserved in RESERVED_KEYS for the command or tool still to come
//   'app'       left to the app and the operating system (close, quit, save --
//               PlexiiDraw saves as you work -- and document switching)

export interface IllustratorShortcut {
  section: string
  action: string
  win: string
  mac: string
  context: 'global' | 'type' | 'gesture'
  key?: string
  /** Set only where Windows uses a different chord. */
  winKey?: string
  target?: string
  /** Where the row comes from when it is not Adobe's help page. */
  source?: string
}

